"""Implementation of actions for the 3rd Party, Embedded Explorer application"""

from typing import Tuple
from interops.libraries.squish_actions import CommonActions
from .objects.embedded_explorer_objects import EmbeddedExplorer


def get_file_list_children() -> Tuple[object]:
    """Locates the main explorer window > grabs all the child objects
    of the current explorer list view > returns them as a Tuple of objects.

    :return: A Tuple of objects
    :rtype Tuple[object]:
    """
    CommonActions.find_object(EmbeddedExplorer.embedded_Explorer_Window)
    return CommonActions.get_child_objects(EmbeddedExplorer.embedded_Explorer_File_ListView)

def click_list_item(listItemObject: object) -> None:
    """Performs a primary mouse click actions on a given list item object

    :param object listItemObject: List item object to be clicked
    """
    CommonActions.left_click_object(listItemObject)

def shift_click_list_item(listItemObject: object) -> None:
    """Performs a shift + primary mouse click actions on a given list item object

    :param object listItemObject: List item object to be shift clicked
    """
    CommonActions.shift_click_object(listItemObject)

def drag_from_explorer(srcObject: object, target_x: int, target_y: int) -> None:
    """Performs a drag and drop action starting from a specific object to a given XY location.

    :param object srcObject: Starting object where the action will begin
    :param int target_x: X axis coordinate of the end point
    :param int target_y: Y axis coordinate of the end point
    """
    CommonActions.mouse_press_and_drag_start(srcObject)
    CommonActions.mouse_press_and_drag_end(target_x + 5 , target_y + 5)